function addLink(a,b){if(!a||!b||a===b)return note(T("请选择不同设施","Select another facility"));if(hasLink(a,b))return note(T("物流线路已经存在","Logistics link already exists"));const allowed=(a==="material"&&b==="crystal")||(a==="crystal"&&b==="depot")||(a==="material"&&b==="manufacturing")||(a==="manufacturing"&&b==="depot");if(!allowed)return note(T("输入与输出类型不匹配","Input and output types do not match"));S.links.push([a,b]);S.linkStart=null;if(S.tutorial===4&&a==="material"&&b==="crystal")S.tutorial=5;if(S.tutorial===5&&a==="crystal"&&b==="depot")S.tutorial=6;note(T("物流线路接通","Logistics connected"));}
