function production(id){const l=S.buildings[id].level,industry=(typeof hasSkill6==="function"&&hasSkill6("industryCore")?1.1:1)*(typeof hasSkill6==="function"&&hasSkill6("overclock")?1.15:1)*(typeof hasSkill6==="function"&&hasSkill6("industrialMastery")?1.2:1),storage=(typeof hasSkill6==="function"&&hasSkill6("flowControl")?1.2:1)*(typeof hasSkill6==="function"&&hasSkill6("warehouseMatrix")?1.35:1),base=id==="crystal"?{rate:12*l,cap:240+260*l}:{rate:8*l,cap:160+180*l};return{rate:Math.round(base.rate*industry*10)/10,cap:Math.round(base.cap*storage)};}
function sync(){let dirty=false,at=now();for(const id of ["material","crystal"]){if(!S.layout[id])continue;const b=S.buildings[id],p=production(id),elapsed=Math.max(0,at-(+b.lastAt||at)),network=id==="material"?powered(id):(powered(id)&&hasLink("material","crystal")&&hasLink("crystal","depot"));if(!network){b.status=powered(id)?"blocked":"offline";b.lastAt=at;continue;}if(elapsed>=1000){b.stored=Math.min(p.cap,(+b.stored||0)+elapsed/3600000*p.rate);b.lastAt=at;b.status=b.stored>=p.cap?"collectable":"producing";dirty=true;}}if(S.craft&&S.craft.status==="crafting"&&at>=S.craft.endAt){S.craft.status="complete";S.buildings.manufacturing.status="collectable";dirty=true;}if(dirty)save();}
function upgradeCost(id){return Math.round((DEF[id].cost||95)*Math.pow(1.55,S.buildings[id].level-1));}
function upgrade(id){const b=S.buildings[id],d=DEF[id],n=upgradeCost(id);if(d.req&&S.buildings.command.level<d.req)return note(T("需要指挥中心 Lv."+d.req,"Requires Command Center Lv."+d.req));if(b.level>=d.max)return note(T("已达到当前等级上限","Current level cap reached"));if(S.screws<n)return note(T("螺丝不足","Not enough screws"));S.screws-=n;b.level++;note(T("升级成功","Upgrade complete"));}
function collect(id){sync();const b=S.buildings[id],n=Math.floor(b.stored||0);if(!n)return note(T("暂无可领取资源","Nothing to collect"));if(id==="crystal")S.coins+=n;else S.materials+=n;b.stored-=n;b.status="producing";note(T("领取成功 +","Collected +")+n);}
function collectAll(){let total=0;for(const id of ["crystal","material"]){if(!S.layout[id])continue;sync();const b=S.buildings[id],n=Math.floor(b.stored||0);if(n){if(id==="crystal")S.coins+=n;else S.materials+=n;b.stored-=n;b.status="producing";total+=n;}}note(total?T("集中领取完成 +","Quick collect +")+total:T("暂无可领取资源","Nothing to collect"));}
