function confirmBuy(){const p=S.pendingPurchase;if(!p)return;const it=SHOP[p.index],left=it?shopStockLeft(it):0,qty=Math.min(Math.max(1,+p.qty||1),left),total=it?shopPrice11(it)*qty:0;S.pendingPurchase=null;if(!it||!qty)return note(T("商品状态已变化","Item availability changed"));if(S.coins<total)return note(T("晶体币不足","Not enough Crystal Coins"));S.coins-=total;if(!it.unlimited)S.shopBought[it.id]=itemBought(it)+qty;if(it.type==="local")S[it.key]+=it.amount*qty;else if(it.type==="resource")addResource8(it.key,it.amount*qty);else if(g.grantPZCrystalWarReward){const pack={};for(const k of Object.keys(it.pack))pack[k]=it.pack[k]*qty;g.grantPZCrystalWarReward(pack);}note(T("兑换成功","Exchange complete"));}
