function rewardLabel(r){const a=[];if(r.crystals)a.push("◆"+r.crystals);if(r.gold)a.push(T("金币 ","Gold ")+r.gold);if(r.expBooks)a.push(T("经验书 ","EXP ")+r.expBooks);if(r.weaponOre)a.push(T("合金 ","Ore ")+r.weaponOre);if(r.coins)a.push("◇"+r.coins);if(r.screws)a.push("🔩"+r.screws);return a.join(" · ");}
function claimLevel(lv){if(lv>S.level)return note(T("等级未达到","Level not reached"));if(S.claimedLevels.includes(lv))return note(T("奖励已领取","Reward already claimed"));const r=levelReward(lv);S.coins+=r.coins||0;S.screws+=r.screws||0;if(g.grantPZCrystalWarReward)g.grantPZCrystalWarReward(r);S.claimedLevels.push(lv);note(T("等级奖励已领取","Level reward claimed"));}
