function canPlace(id,x,y){const d=DEF[id];return x>=0&&y>=0&&x+d.w<=GRID.cols&&y+d.h<=GRID.rows&&!cellOccupied(x,y,id);}
function place(id,x,y){const d=DEF[id];if(S.layout[id])return note(T("该设施已部署","Facility already deployed"));if(d.req&&S.buildings.command.level<d.req)return note(T("需要指挥中心 Lv."+d.req,"Requires Command Center Lv."+d.req));if(!canPlace(id,x,y))return note(T("此处无法部署","Cannot deploy here"));if(S.screws<d.cost)return note(T("螺丝不足","Not enough screws"));S.screws-=d.cost;S.layout[id]={x,y};S.buildings[id].lastAt=now();S.buildings[id].status=powered(id)?"normal":"offline";S.buildMode=null;const expected=["power","material","crystal","depot"][S.tutorial];if(id===expected)S.tutorial++;note(T("设施部署完成","Facility deployed"));}
