function resourceName8(k){const n={rawOre:["晶体原矿","Raw Crystal"],materials:["基础原料","Base Materials"],wood:["荒地木材","Wasteland Timber"],resin:["晶化树脂","Crystal Resin"],stone:["结构岩","Structural Stone"],herbs:["复生植株","Revival Herb"],copper:["导能铜矿","Conductive Copper"],coolant:["低温冷却液","Cryo Coolant"],ceramic:["耐热陶瓷","Heatproof Ceramic"],sulfur:["晶硫矿","Crystal Sulfur"],quartz:["高纯石英","Pure Quartz"],biomass:["活性生物质","Active Biomass"],flux:["导能流体","Conductive Flux"],scrap:["废墟合金","Ruin Alloy"],fiber:["合成纤维","Synth Fiber"],powder:["晶体粉末","Crystal Powder"],composite:["稳定复材","Stable Composite"],treatedWood:["稳定木材","Stabilized Timber"],alloyPlate:["废区合金板","Ruin Alloy Plate"],crystalCable:["晶体线缆","Crystal Cable"],circuitBoard:["控制电路板","Control Circuit"],opticalLens:["晶体光学镜","Crystal Optics"],ceramicPlate:["耐热陶瓷板","Heatproof Ceramic Plate"],coolantCapsule:["冷却循环舱","Coolant Capsule"],powerCell:["工业电芯","Power Cell"],logisticsUnit:["物流控制单元","Logistics Controller"],sensorArray:["前线传感阵列","Front Sensor Array"],repairKit:["无人机维修组件","Drone Repair Kit"],defenseCore:["防御运算核心","Defense Processor"],siegeModule:["重炮增压模组","Siege Booster"],blueprintChip:["蓝图演算芯片","Blueprint Compute Chip"],fluxCoil:["导能线圈","Flux Coil"],quartzLens:["石英聚焦镜","Quartz Focus Lens"],bioGel:["活性修复凝胶","Active Repair Gel"],thermalCharge:["晶硫热能芯","Sulfur Thermal Core"]};return T(...(n[k]||[k,k]));}
