function maxHp8(v){return Math.round((v.type==="command"?350:145)+v.level*42)*(hasSkill6("fortifiedGrid")?1.25:1)*(hasSkill6("armorPlating")?1.15:1);}
function upgradeQuote8(v){const d=DEF[v.type],screws=Math.ceil(2.7*(d.cost||80)*(1.15+v.level*.72)*Math.pow(1.27,Math.max(0,v.level-1))),parts={};if(v.level>=2)parts.alloyPlate=Math.ceil(v.level/3);if(v.level>=4)parts.circuitBoard=Math.ceil((v.level-2)/3);if(["defense","turret","slowTower","artillery"].includes(v.type)&&v.level>=5)parts.defenseCore=1;return{screws,parts};}
