function repair8(v){const max=maxHp8(v),missing=Math.max(0,max-v.hp);if(!missing)return note(T("设备耐久正常","Facility durability is full"));const cost=repairCost8(v);if(!spendScrews11(cost))return note(T("维修所需螺丝不足","Not enough Screws to repair"));v.hp=max;v.status="normal";sendWorldEvent12("device_upgraded",v.iid,{scope:"base",instance:v,screwsDelta:-cost});note(T("维修完成","Repair complete"));}
